#!/usr/bin/env node
// Builds the public /training/ mirror of the AutoLander Customer Learning Library.
//
//   npm run training:build            (source: E:/al-training-src-20260922, override with TRAINING_SRC=…)
//
// EVERYTHING under public/training/ is generated by this script — the directory is deleted and
// rebuilt on every run, so hand edits there are lost. Change the source package, the templates in
// scripts/training/templates/ (site.css, demo.js, player.js) or the transforms below instead.
//
// What it does (design: docs/superpowers/specs/2026-09-22-growth-train-design.md §1):
//   1. Copies the staged library into public/training/ with the library's own `training/` folder
//      MERGED into the mount root (training/player/** -> player/**, etc.). Drops README.txt,
//      YOUTUBE_UPLOAD_GUIDE_V12.txt, every .mp4 and cdn-cgi/. START_HERE.html becomes a tiny
//      meta-refresh alias to /training/ (index.html is the real page).
//   2. Rewrites every relative href/src for the new layout and asserts each one resolves to a file
//      that was actually published.
//   3. Strips the Cloudflare `__CF$cv$params` challenge script the review site appended to every
//      page, replaces the private-review `noindex` robots meta with `index,follow`, adds a
//      canonical <link>, retitles the pages, and adds the slim autolander.ai top bar + site.css.
//   4. Swaps the local MP4 <video> players for YouTube embeds: the demo page embeds i5uUB5OxIhk
//      with chapter buttons built from demo/renders/AUTOLANDER_DEMO_V11_YOUTUBE_CHAPTERS.txt; the
//      course player embeds ePsAvCZWw_A and seeks per lesson (see templates/player.js). The
//      player's course-data JSON loses its .mp4 `video` fields and gains `youtubeVideoId`.
//   5. Sanity-checks every lesson's combinedStart against
//      training/renders/AUTOLANDER_TRAINING_V12_YOUTUBE_CHAPTERS.txt and prints the mapping
//      (mismatches are REPORTED, never silently corrected).
//   6. Asserts that no published HTML/JS/CSS still contains an un-rebased `training/player|manuals|
//      workbooks|renders` path (the only permitted occurrence is inside the canonical
//      `https://autolander.ai/training/…` URL), README.txt, YOUTUBE_UPLOAD_GUIDE, chatgpt.site,
//      cdn-cgi, __CF$cv$params or .mp4. Exit 1 on any failure.

import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync, copyFileSync } from 'node:fs';
import { dirname, join, relative, resolve, sep, posix } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..');
const SRC = resolve(process.env.TRAINING_SRC || 'E:/al-training-src-20260922');
const PUBLIC_DIR = resolve(ROOT, 'public');
const OUT = resolve(PUBLIC_DIR, 'training');
const TEMPLATES = resolve(ROOT, 'scripts', 'training', 'templates');

const ORIGIN = 'https://autolander.ai';
const BASE_PATH = '/training/';
const CANONICAL_PREFIX = ORIGIN + BASE_PATH; // the one place `training/player` etc. may legitimately appear
const DEMO_VIDEO_ID = 'i5uUB5OxIhk';
const COURSE_VIDEO_ID = 'ePsAvCZWw_A';
const EMBED_ATTRS = 'allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"';
const ATTRIBUTION_TAG = '<script defer src="/al-attribution-v1.js"></script>'; // same tag index.html / privacy.html / the SEO shell use
const embedUrl = (id) => `https://www.youtube-nocookie.com/embed/${id}?cc_load_policy=1&amp;cc_lang_pref=en&amp;rel=0`;
const watchUrl = (id) => `https://www.youtube.com/watch?v=${id}`;

const DROP_FILES = new Set(['README.txt', 'YOUTUBE_UPLOAD_GUIDE_V12.txt', 'START_HERE.html']);
const DROP_DIRS = new Set(['cdn-cgi']);
const FORBIDDEN_LITERALS = ['README.txt', 'YOUTUBE_UPLOAD_GUIDE', 'chatgpt.site', 'cdn-cgi', '__CF$cv$params', '.mp4'];
const UNREBASED_RE = /training\/(player|manuals|workbooks|renders)/g;

// ---------------------------------------------------------------- helpers
class BuildError extends Error {}
const fail = (msg) => { throw new BuildError(msg); };
const read = (p) => readFileSync(p, 'utf8');
const readTemplate = (name) => read(join(TEMPLATES, name));
const toPosix = (p) => p.split(sep).join('/');
const escHtml = (s) => String(s).replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
const escAttr = (s) => escHtml(s).replaceAll('"', '&quot;').replaceAll("'", '&#x27;');
const mmss = (secs) => `${Math.floor(secs / 60)}:${String(Math.floor(secs % 60)).padStart(2, '0')}`;

function countOf(hay, needle) {
  let n = 0;
  for (let i = hay.indexOf(needle); i !== -1; i = hay.indexOf(needle, i + needle.length)) n += 1;
  return n;
}
// Exact-string replacement that refuses to run if the anchor is missing (or ambiguous unless `all`).
function mustReplace(text, needle, replacement, label, { all = false, min = 1 } = {}) {
  const n = countOf(text, needle);
  if (n < min || (!all && n !== 1)) fail(`${label}: expected ${all ? `>= ${min}` : 'exactly 1'} occurrence(s) of ${JSON.stringify(needle.slice(0, 80))}, found ${n}`);
  return all ? text.replaceAll(needle, replacement) : text.replace(needle, () => replacement);
}
function mustReplaceRe(text, re, replacement, label, { min = 1, max = Infinity } = {}) {
  const n = (text.match(re) || []).length;
  if (n < min || n > max) fail(`${label}: expected ${min}..${max === Infinity ? '∞' : max} match(es) of ${re}, found ${n}`);
  return text.replace(re, replacement);
}
// Replace [start-of-`open`, start-of-`close`) — `close` is the first occurrence AFTER `open`.
function replaceBetween(text, open, close, replacement, label) {
  const a = text.indexOf(open);
  if (a === -1 || text.indexOf(open, a + 1) !== -1) fail(`${label}: open marker ${JSON.stringify(open)} must occur exactly once`);
  const b = text.indexOf(close, a + open.length);
  if (b === -1) fail(`${label}: close marker ${JSON.stringify(close)} not found after the open marker`);
  return text.slice(0, a) + replacement + text.slice(b);
}
// Replace a whole element: from `open` through the first `close` after it (inclusive).
function replaceElement(text, open, close, replacement, label) {
  const a = text.indexOf(open);
  if (a === -1 || text.indexOf(open, a + 1) !== -1) fail(`${label}: open marker ${JSON.stringify(open)} must occur exactly once`);
  const b = text.indexOf(close, a + open.length);
  if (b === -1) fail(`${label}: close marker ${JSON.stringify(close)} not found after the open marker`);
  const end = b + close.length;
  const element = text.slice(a, end);
  return text.slice(0, a) + (typeof replacement === 'function' ? replacement(element) : replacement) + text.slice(end);
}

// Cloudflare bot-challenge script the review host appended before </body> on every page.
const CF_SCRIPT_RE = /<script>\(function\(\)\{function c\(\)\{var b=a\.contentDocument[\s\S]*?__CF\$cv\$params[\s\S]*?<\/script>/g;
function stripCloudflare(html, label) {
  return mustReplaceRe(html, CF_SCRIPT_RE, '', `${label}: Cloudflare challenge script`, { min: 1, max: 1 });
}

const TOPBAR_LINKS = [
  ['home', 'Training home', ''],
  ['course', 'Course', 'player/index.html'],
  ['manuals', 'Manuals', 'manuals/index.html'],
  ['demo', 'Demo', 'demo/index.html'],
];
function topBar(up, currentKey) {
  const links = TOPBAR_LINKS.map(([key, label, rel]) =>
    `<a href="${rel ? up + rel : (up || './')}"${key === currentKey ? ' aria-current="page"' : ''}>${label}</a>`).join('');
  return `<div class="al-topbar"><div class="al-topbar-inner">`
    + `<a class="al-topbar-brand" href="${ORIGIN}/" aria-label="AutoLander home"><img src="${up}../autolander-logo-240.webp" alt="AutoLander" width="240" height="72" decoding="async"></a>`
    + `<nav class="al-topbar-nav" aria-label="AutoLander training">${links}<a class="al-topbar-back" href="${ORIGIN}/">Back to autolander.ai</a></nav>`
    + `</div></div>`;
}

// Chrome shared by every published page: CF strip, robots + canonical, title, site.css, top bar.
function pageChrome(html, { label, depth, canonical, title, currentKey }) {
  const up = '../'.repeat(depth);
  html = stripCloudflare(html, label);
  html = mustReplace(html, '<meta name="robots" content="noindex,nofollow,noarchive">',
    `<meta name="robots" content="index,follow">\n<link rel="canonical" href="${CANONICAL_PREFIX}${canonical}">`, `${label}: robots meta`);
  html = mustReplaceRe(html, /<title>[^<]*<\/title>/, () => `<title>${escHtml(title)}</title>`, `${label}: <title>`, { min: 1, max: 1 });
  html = mustReplaceRe(html, /<link rel="stylesheet" href="[^"]+">/, (m) => `${m}<link rel="stylesheet" href="${up}site.css">`, `${label}: stylesheet link`, { min: 1, max: 1 });
  html = mustReplaceRe(html, /<header\b/, () => `${topBar(up, currentKey)}<header`, `${label}: <header>`, { min: 1, max: 1 });
  // Site convention (pinned by test/organic-attribution.test.js): every indexable page loads the
  // first-touch attribution capture exactly once. It is localStorage-only — no network, no pixel.
  html = mustReplace(html, '</head>', `${ATTRIBUTION_TAG}</head>`, `${label}: </head>`);
  return html;
}

// "00:00 Title" / "00:01:05 Title" lines -> [{seconds, title}]
function parseChapters(text, label) {
  const rows = [];
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trim();
    if (!line) continue;
    const m = line.match(/^(\d{1,2}):(\d{2})(?::(\d{2}))?\s+(.+)$/);
    if (!m) fail(`${label}: unparseable chapter line ${JSON.stringify(line)}`);
    const [, a, b, c, title] = m;
    const seconds = c === undefined ? Number(a) * 60 + Number(b) : Number(a) * 3600 + Number(b) * 60 + Number(c);
    rows.push({ seconds, title: title.trim() });
  }
  if (!rows.length || rows[0].seconds !== 0) fail(`${label}: chapter list must start at 00:00`);
  return rows;
}

// ---------------------------------------------------------------- per-page transforms
function transformIndex(html) {
  html = pageChrome(html, { label: 'index.html', depth: 0, canonical: '', title: 'AutoLander Training', currentKey: 'home' });
  html = mustReplace(html, 'href="START_HERE.html"', 'href="./"', 'index.html: brand link');
  html = mustReplace(html, 'href="training/', 'href="', 'index.html: training/ hrefs', { all: true, min: 10 });
  html = mustReplace(html, 'src="training/', 'src="', 'index.html: training/ srcs', { all: true, min: 1 });
  html = mustReplace(html,
    '<a href="README.txt">Read the quick start and file guide →</a><p><a href="YOUTUBE_UPLOAD_GUIDE_V12.txt">Standalone videos, captions and YouTube chapters →</a></p>',
    '<a href="player/chapter_index.html">See the course map and workbook pages →</a>',
    'index.html: "Using the files" internal links');
  return html;
}

function transformDemo(html, demoChapters) {
  html = pageChrome(html, { label: 'demo/index.html', depth: 1, canonical: 'demo/index.html', title: 'AutoLander Training · Demo', currentKey: 'demo' });
  html = mustReplace(html, 'href="../START_HERE.html"', 'href="../"', 'demo: START_HERE links', { all: true, min: 2 });
  html = mustReplace(html, 'href="../training/', 'href="../', 'demo: ../training/ hrefs', { all: true, min: 4 });
  // <video> + caption band + player buttons -> YouTube embed (JS upgrades it to an API player)
  html = replaceBetween(html, '<div class="video-box">', '<div class="video-tools">',
    `<div class="video-box"><div id="demo" class="yt-embed"><div class="yt-loading">Loading the demo video…</div>`
    + `<noscript><iframe src="${embedUrl(DEMO_VIDEO_ID)}" title="AutoLander product demo" ${EMBED_ATTRS}></iframe></noscript></div></div>`,
    'demo: video box');
  html = mustReplace(html, '<div class="video-tools"><span>8:47 · 1080p · ElevenLabs narration</span></div>',
    '<div class="video-tools"><span>8:47 · 1080p · Captions available from the player’s CC button</span></div>', 'demo: video tools');
  html = mustReplaceRe(html, /<p class="demo-note">[^<]*<\/p>/,
    () => '<p class="demo-note">Use the chapter list to jump to a section. Captions are available from the player’s CC button. Incoming Messenger notifications are shown as an illustration; AutoLander does not reply to buyers.</p>',
    'demo: note', { min: 1, max: 1 });
  html = replaceBetween(html, '<div class="downloads">', '<p id="play-status"',
    `<div class="downloads"><a href="renders/AUTOLANDER_DEMO_V11_ELEVENLABS_1080P.transcript.txt">Read transcript</a>`
    + `<a href="renders/AUTOLANDER_DEMO_V11_ELEVENLABS_1080P.chapters.txt">Chapter list</a>`
    + `<a href="${watchUrl(DEMO_VIDEO_ID)}" target="_blank" rel="noopener">Watch on YouTube ↗</a></div>`,
    'demo: downloads');
  const buttons = demoChapters.map((c) =>
    `<button type="button" data-time="${c.seconds}" data-title="${escAttr(c.title)}"><time>${mmss(c.seconds)}</time><span>${escHtml(c.title)}</span></button>`).join('\n');
  html = replaceElement(html, '<nav class="chapters"', '</nav>',
    `<nav class="chapters" aria-label="Demo chapters"><h2>Jump to a section</h2>${buttons}</nav>`, 'demo: chapter nav');
  html = replaceElement(html, '<script id="caption-data"', '</script>', '', 'demo: caption-data JSON');
  return html;
}

function transformPlayer(html, courseChapters, report) {
  html = pageChrome(html, { label: 'player/index.html', depth: 1, canonical: 'player/index.html', title: 'AutoLander Training · Course', currentKey: 'course' });
  // The offline package's CSP (default-src 'self') would block the YouTube iframe, and a missing
  // referrer makes YouTube refuse embeds (player error 153).
  html = mustReplaceRe(html, /\s*<meta http-equiv="Content-Security-Policy"[^>]*>/, '', 'player: CSP meta', { min: 1, max: 1 });
  html = mustReplace(html, '<meta name="referrer" content="no-referrer">', '<meta name="referrer" content="strict-origin-when-cross-origin">', 'player: referrer meta');
  // <video> + placeholder + caption band + fullscreen controls -> embed mount (closes .video-wrap)
  html = replaceBetween(html, '<video id="film"', '<p id="media-message"',
    `<div id="film" class="yt-embed"><div class="yt-loading">Loading the course video…</div>`
    + `<noscript><iframe src="${embedUrl(COURSE_VIDEO_ID)}" title="AutoLander training course" ${EMBED_ATTRS}></iframe></noscript></div></div>\n      `,
    'player: video element');
  html = replaceBetween(html, '<button id="captions-toggle"', '<label for="playback-speed">', '', 'player: captions/fullscreen toggles');
  html = mustReplace(html, '<p class="muted">Use the combined course, or choose any individual lesson above.</p>',
    '<p class="muted">Watch the whole course in one sitting on YouTube, or choose any lesson above.</p>', 'player: combined-course blurb');
  html = replaceBetween(html, '<a id="combined-clean"', '<a id="workbook-navigation"',
    `<a id="combined-clean" href="${watchUrl(COURSE_VIDEO_ID)}" target="_blank" rel="noopener">Watch the full course on YouTube ↗</a>\n`,
    'player: combined-course links');
  html = replaceElement(html, '<p id="combined-pending"', '</p>', '', 'player: combined-pending note');
  html = mustReplaceRe(html, /<p class="fine-print">\s*<a href="\.\.\/\.\.\/YOUTUBE_UPLOAD_GUIDE_V12\.txt">[\s\S]*?<\/p>/, '',
    'player: YouTube upload guide / chapters / SRT links', { min: 1, max: 1 });
  html = mustReplace(html, '<p>Training V12 · Shared review course</p>', '<p>Training V12 · AutoLander customer course</p>', 'player: footer');
  html = mustReplaceRe(html, /<div class="noscript">[^<]*<\/div>/,
    () => '<div class="noscript">Enable JavaScript to use lesson navigation. The transcripts, captions and PDFs remain available from the links on this page.</div>',
    'player: noscript', { min: 1, max: 1 });
  html = replaceElement(html, '<script id="course-data"', '</script>', (element) => {
    const json = element.slice(element.indexOf('>') + 1, element.lastIndexOf('</script>'));
    const data = JSON.parse(json);
    for (const lesson of data.lessons) delete lesson.video; // per-lesson .mp4 renders are not published
    delete data.resources.cleanCourse;      // full-course .mp4 -> hardcoded YouTube link above
    delete data.resources.captionedCourse;  // burned-in-captions .mp4 -> YouTube CC
    data.youtubeVideoId = COURSE_VIDEO_ID;
    report.chapterCheck = checkCourseChapters(data.lessons, courseChapters);
    const serialized = JSON.stringify(data).replace(/<\//g, '<\\/'); // keep "</script>" out of the inline JSON
    return `<script id="course-data" type="application/json">${serialized}</script>`;
  }, 'player: course-data JSON');
  return html;
}

function transformChapterIndex(html) {
  html = pageChrome(html, { label: 'player/chapter_index.html', depth: 1, canonical: 'player/chapter_index.html', title: 'AutoLander Training · Course map', currentKey: 'course' });
  html = mustReplaceRe(html, /href="\.\.\/renders\/AUTOLANDER_TRAINING_V12_ELEVENLABS_1080P\.mp4#t=([0-9.]+)"/g,
    (m, t) => `href="${watchUrl(COURSE_VIDEO_ID)}&amp;t=${Math.floor(Number(t))}s"`, 'chapter_index: full-course mp4 links', { min: 18, max: 18 });
  html = mustReplace(html, '<th scope="col">Combined video</th>', '<th scope="col">Full course (YouTube)</th>', 'chapter_index: column header');
  html = mustReplace(html, 'jump to its place in the combined video', 'jump to its place in the full course video on YouTube', 'chapter_index: intro');
  html = mustReplace(html, '<caption>18 lessons. Exact start times refer to the combined course; standalone lessons each start at 00:00.</caption>',
    '<caption>18 lessons. Start times refer to the full course video on YouTube; each link opens the video at that lesson.</caption>', 'chapter_index: caption');
  html = mustReplace(html, '<p>Training V12 · Shared review course · No telemetry</p>', '<p>Training V12 · No telemetry</p>', 'chapter_index: footer');
  return html;
}

function transformManuals(html) {
  html = pageChrome(html, { label: 'manuals/index.html', depth: 1, canonical: 'manuals/index.html', title: 'AutoLander Training · Manuals', currentKey: 'manuals' });
  html = mustReplace(html, 'Works offline. No account tracking.', 'No account tracking.', 'manuals: sidebar foot', { all: true });
  html = mustReplace(html, 'Store the latest learning-library folder in one known place. Use its edition date and lesson IDs.',
    'Bookmark autolander.ai/training as the one place for the latest library. Use its edition date and lesson IDs.', 'manuals: library-folder advice', { all: true });
  html = mustReplace(html, 'Choose a lesson in the player. Keep the library folders together so these links work offline.',
    'Choose a lesson in the player.', 'manuals: offline-links advice', { all: true });
  return html;
}

function transformManualJs(js) {
  js = mustReplace(js, "document.title='AutoLander | '+item.title;", "document.title=item.title+' · AutoLander Training';", 'manual.js: document.title');
  js = mustReplace(js, "'Task link copied. Local file links work on this computer; share the complete library folder for another computer.'", "'Task link copied.'", 'manual.js: copy message');
  js = mustReplace(js, "Use this page\\'s address bar to copy its local link.'", "Use this page\\'s address bar to copy its link.'", 'manual.js: copy fallback');
  return js;
}

const START_HERE_ALIAS = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AutoLander Training</title><meta name="robots" content="index,follow"><link rel="canonical" href="${CANONICAL_PREFIX}"><meta http-equiv="refresh" content="0; url=./">${ATTRIBUTION_TAG}</head>
<body><p>The AutoLander training library is at <a href="./">autolander.ai/training</a>.</p></body></html>
`;

// ---------------------------------------------------------------- chapter sanity check
function checkCourseChapters(lessons, chapters) {
  const issues = [];
  const rows = lessons.map((lesson) => {
    const start = Math.floor(lesson.combinedStart);
    const hit = chapters.find((c) => c.seconds === start);
    if (!hit) issues.push(`${lesson.shortId} starts at ${start}s (${mmss(start)}) but no YouTube chapter begins there`);
    return { id: lesson.shortId, start, title: hit ? hit.title : '(no chapter)' };
  });
  // YouTube chapters are whole seconds; a lesson window in chapter terms is [floor(start), floor(end)).
  const orphans = chapters.filter((c) => !lessons.some((l) => c.seconds >= Math.floor(l.combinedStart) && c.seconds < Math.floor(l.combinedEnd)));
  for (const c of orphans) issues.push(`chapter ${mmss(c.seconds)} "${c.title}" falls outside every lesson window`);
  const a0 = lessons[0];
  const withinA0 = chapters.filter((c) => c.seconds >= Math.floor(a0.combinedStart) && c.seconds < Math.floor(a0.combinedEnd));
  const expectedChapters = lessons.length + withinA0.length - 1;
  if (chapters.length !== expectedChapters) issues.push(`expected ${expectedChapters} chapters (${lessons.length} lessons, ${withinA0.length} inside ${a0.shortId}), found ${chapters.length}`);
  return { rows, withinA0: withinA0.map((c) => `${mmss(c.seconds)} ${c.title}`), chapterCount: chapters.length, issues };
}

// ---------------------------------------------------------------- post-build assertions
function listFiles(dir, base = dir) {
  const out = [];
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) out.push(...listFiles(full, base));
    else out.push(toPosix(relative(base, full)));
  }
  return out.sort();
}
function scanForbidden(published) {
  const problems = [];
  for (const rel of published.filter((f) => /\.(html|js|css)$/i.test(f))) {
    const text = read(join(OUT, rel));
    for (const needle of FORBIDDEN_LITERALS) {
      const at = text.indexOf(needle);
      if (at !== -1) problems.push(`${rel}: contains "${needle}" (…${text.slice(Math.max(0, at - 40), at + needle.length + 20).replace(/\s+/g, ' ')}…)`);
    }
    for (const m of text.matchAll(UNREBASED_RE)) {
      // `training/player` etc. may only appear as part of the canonical https://autolander.ai/training/… URL.
      const before = text.slice(Math.max(0, m.index - (ORIGIN.length + 1)), m.index);
      if (before !== ORIGIN + '/') problems.push(`${rel}: un-rebased path "${m[0]}" (…${text.slice(Math.max(0, m.index - 30), m.index + 40).replace(/\s+/g, ' ')}…)`);
    }
  }
  return problems;
}
function checkLinks(published) {
  const problems = [];
  const set = new Set(published);
  for (const rel of published.filter((f) => f.endsWith('.html'))) {
    const html = read(join(OUT, rel));
    const dir = posix.dirname(rel);
    // A rewrite that mangles an attribute (e.g. href="../"manuals/…) leaves a quote glued to text.
    for (const m of html.matchAll(/\b(?:href|src|poster)="[^"]*"[^\s>]/g)) {
      problems.push(`${rel}: malformed attribute near "${html.slice(m.index, m.index + 60).replace(/\s+/g, ' ')}"`);
    }
    const refs = [...html.matchAll(/\b(?:href|src|poster)=["']([^"']+)["']/g)].map((m) => m[1]);
    if (rel === 'player/index.html') {
      const data = JSON.parse(html.match(/<script id="course-data"[^>]*>([\s\S]*?)<\/script>/)[1]);
      for (const lesson of data.lessons) refs.push(lesson.vtt, lesson.srt, lesson.transcriptFile);
      refs.push(...Object.values(data.resources));
    }
    for (const ref of refs) {
      if (!ref || /^(https?:|mailto:|data:|javascript:|#)/i.test(ref)) continue;
      const target = ref.split('#')[0].split('?')[0];
      if (!target) continue;
      let abs;
      if (target.startsWith('/')) abs = join(PUBLIC_DIR, target);
      else abs = join(OUT, posix.normalize(posix.join(dir === '.' ? '' : dir, target)));
      if (target.endsWith('/')) abs = join(abs, 'index.html');
      if (!existsSync(abs)) problems.push(`${rel}: ${ref} -> ${abs} does not exist`);
    }
  }
  for (const must of ['index.html', 'START_HERE.html', 'site.css', 'library.css', 'favicon.svg', 'demo/index.html', 'demo/demo.js',
    'player/index.html', 'player/player.js', 'player/styles.css', 'player/chapter_index.html', 'manuals/index.html', 'manuals/manual.js', 'manuals/manual.css',
    'manuals/AutoLander_Sales_Rep_Manual_and_Success_Guide_V03.pdf', 'manuals/AutoLander_Manager_Manual_and_Success_Guide_V03.pdf',
    'workbooks/output/pdf/AutoLander_Learner_Workbook_V11.pdf', 'workbooks/output/pdf/AutoLander_Manager_Coaching_Guide_V11.pdf',
    'renders/AUTOLANDER_TRAINING_V12_YOUTUBE_CHAPTERS.txt', 'demo/renders/AUTOLANDER_DEMO_V11_YOUTUBE_CHAPTERS.txt']) {
    if (!set.has(must)) problems.push(`required file missing from the mirror: ${must}`);
  }
  return problems;
}

// ---------------------------------------------------------------- main
function main() {
  if (!existsSync(join(SRC, 'index.html')) || !existsSync(join(SRC, 'training', 'player', 'index.html'))) {
    fail(`source package not found at ${SRC} (set TRAINING_SRC=<dir>)`);
  }
  const demoChapters = parseChapters(read(join(SRC, 'demo', 'renders', 'AUTOLANDER_DEMO_V11_YOUTUBE_CHAPTERS.txt')), 'demo chapters');
  const courseChapters = parseChapters(read(join(SRC, 'training', 'renders', 'AUTOLANDER_TRAINING_V12_YOUTUBE_CHAPTERS.txt')), 'course chapters');
  const report = { copied: 0, transformed: [], dropped: [], chapterCheck: null };

  const TRANSFORMS = {
    'index.html': (text) => transformIndex(text),
    'demo/index.html': (text) => transformDemo(text, demoChapters),
    'demo/demo.js': () => readTemplate('demo.js'),
    'player/index.html': (text) => transformPlayer(text, courseChapters, report),
    'player/player.js': () => readTemplate('player.js'),
    'player/chapter_index.html': (text) => transformChapterIndex(text),
    'manuals/index.html': (text) => transformManuals(text),
    'manuals/manual.js': (text) => transformManualJs(text),
  };

  rmSync(OUT, { recursive: true, force: true });
  mkdirSync(OUT, { recursive: true });

  // 1. mount + rebase: training/** merges into the mount root; drops applied.
  const plan = new Map(); // published rel -> source rel
  const walk = (dir) => {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const full = join(dir, entry.name);
      const rel = toPosix(relative(SRC, full));
      if (entry.isDirectory()) { if (!DROP_DIRS.has(entry.name)) walk(full); continue; }
      if (DROP_FILES.has(rel) || rel.toLowerCase().endsWith('.mp4') || rel.split('/').some((seg) => DROP_DIRS.has(seg))) { report.dropped.push(rel); continue; }
      const published = rel.startsWith('training/') ? rel.slice('training/'.length) : rel;
      if (plan.has(published)) fail(`mount collision: ${rel} and ${plan.get(published)} both publish as ${published}`);
      plan.set(published, rel);
    }
  };
  walk(SRC);

  for (const [published, sourceRel] of [...plan.entries()].sort()) {
    const dest = join(OUT, published);
    mkdirSync(dirname(dest), { recursive: true });
    const transform = TRANSFORMS[published];
    if (transform) {
      writeFileSync(dest, transform(read(join(SRC, sourceRel))), 'utf8');
      report.transformed.push(published);
    } else {
      copyFileSync(join(SRC, sourceRel), dest);
      report.copied += 1;
    }
  }
  for (const name of Object.keys(TRANSFORMS)) if (!plan.has(name)) fail(`expected source file for ${name} was not found in the package`);

  writeFileSync(join(OUT, 'START_HERE.html'), START_HERE_ALIAS, 'utf8');
  writeFileSync(join(OUT, 'site.css'), readTemplate('site.css'), 'utf8');

  // 2. assertions
  const published = listFiles(OUT);
  const problems = [...checkLinks(published), ...scanForbidden(published)];

  // 3. report
  console.log(`training mirror: ${published.length} files in public/training/ (${report.copied} copied verbatim, ${report.transformed.length} transformed, ${report.dropped.length} dropped)`);
  console.log(`  transformed: ${report.transformed.join(', ')}`);
  console.log(`  dropped:     ${report.dropped.join(', ')}`);
  const check = report.chapterCheck;
  console.log(`\ncombinedStart vs AUTOLANDER_TRAINING_V12_YOUTUBE_CHAPTERS.txt (${check.chapterCount} chapters):`);
  for (const row of check.rows) console.log(`  ${row.id.padEnd(3)} ${mmss(row.start).padStart(5)}  ${row.title}`);
  console.log(`  ${check.rows[0].id} also spans: ${check.withinA0.slice(1).join(' | ') || '(nothing else)'}`);
  if (check.issues.length) {
    console.warn('\n!! chapter mismatches (reported, NOT corrected):');
    for (const issue of check.issues) console.warn(`   - ${issue}`);
  } else {
    console.log('  every lesson start matches a YouTube chapter; every chapter falls inside a lesson.');
  }
  if (problems.length) {
    console.error(`\n!! ${problems.length} assertion failure(s):`);
    for (const p of problems) console.error(`   - ${p}`);
    process.exit(1);
  }
  console.log('\nassertions: every relative link resolves; no un-rebased paths, README/YouTube-guide, chatgpt.site, cdn-cgi, __CF$cv$params or .mp4 in published HTML/JS/CSS.');
}

try {
  main();
} catch (error) {
  if (error instanceof BuildError) { console.error(`\n!! ${error.message}`); process.exit(1); }
  throw error;
}
